# main.py
import os
import json
import requests
from flask import Flask, request, jsonify
from flask_cors import CORS

app = Flask(__name__)
CORS(app)

MODAL_TOKEN_ID = os.environ.get("MODAL_TOKEN_ID")
MODAL_TOKEN_SECRET = os.environ.get("MODAL_TOKEN_SECRET")
SUPERMEMORY_API_KEY = os.environ.get("SUPERMEMORY_API_KEY")

MODAL_ENDPOINT = "https://your-modal-username--glm-4-7-deployment-serve.modal.run/v1/chat/completions"

@app.route("/api/chat", methods=["POST"])
def chat():
    data = request.json
    messages = data.get("messages", [])

    headers = {
        "Authorization": f"Bearer {MODAL_TOKEN_ID}:{MODAL_TOKEN_SECRET}",
        "Content-Type": "application/json"
    }

    payload = {
        "messages": messages,
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 8192
    }

    response = requests.post(MODAL_ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()

    return jsonify(response.json())

@app.route("/api/memory/ingest", methods=["POST"])
def memory_ingest():
    data = request.json
    content = data.get("content")
    container_tag = data.get("containerTag", "tiffytime_default")

    headers = {
        "Authorization": f"Bearer {SUPERMEMORY_API_KEY}",
        "Content-Type": "application/json"
    }

    payload = {
        "content": content,
        "containerTag": container_tag
    }

    response = requests.post("https://api.supermemory.ai/v1/ingest", json=payload, headers=headers)
    response.raise_for_status()

    return jsonify(response.json())

@app.route("/api/memory/search", methods=["POST"])
def memory_search():
    data = request.json
    query = data.get("query")
    container_tag = data.get("containerTag", "tiffytime_default")

    headers = {
        "Authorization": f"Bearer {SUPERMEMORY_API_KEY}",
        "Content-Type": "application/json"
    }

    payload = {
        "query": query,
        "containerTag": container_tag,
        "topK": 50,
        "threshold": 0.7
    }

    response = requests.post("https://api.supermemory.ai/v1/search", json=payload, headers=headers)
    response.raise_for_status()

    return jsonify(response.json())

@app.route("/api/memory/enhance", methods=["POST"])
def memory_enhance():
    data = request.json
    query = data.get("query")
    context = data.get("context", "")

    headers = {
        "Authorization": f"Bearer {SUPERMEMORY_API_KEY}",
        "Content-Type": "application/json"
    }

    search_payload = {
        "query": query,
        "topK": 20,
        "threshold": 0.8
    }

    search_response = requests.post("https://api.supermemory.ai/v1/search", json=search_payload, headers=headers)
    search_response.raise_for_status()
    memories = search_response.json().get("memories", [])

    memory_context = "\n".join([m.get("content", "") for m in memories[:5]])

    chat_headers = {
        "Authorization": f"Bearer {MODAL_TOKEN_ID}:{MODAL_TOKEN_SECRET}",
        "Content-Type": "application/json"
    }

    chat_payload = {
        "messages": [
            {"role": "system", "content": f"Használd ezt a kontextust a válaszhoz:\n{memory_context}"},
            {"role": "user", "content": f"{context}\n\nKérdés: {query}"}
        ],
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 8192
    }

    chat_response = requests.post(MODAL_ENDPOINT, json=chat_payload, headers=chat_headers)
    chat_response.raise_for_status()

    return jsonify(chat_response.json())

